00049 class CABACReader
00050 {
00051 public:
00052   CABACReader(BinDecoderBase& binDecoder) : m_BinDecoder(binDecoder), m_Bitstream(0) {}
00053   virtual ~CABACReader() {}
00054 
00055 public:
00056   void        initCtxModels             ( Slice&                        slice );
00057   void        initBitstream             ( InputBitstream*               bitstream )           { m_Bitstream = bitstream; m_BinDecoder.init( m_Bitstream ); }
00058   const Ctx&  getCtx                    ()                                            const   { return m_BinDecoder.getCtx();  }
00059   Ctx&        getCtx                    ()                                                    { return m_BinDecoder.getCtx();  }
00060 
00061 public:
00062   // slice segment data (clause 7.3.8.1)
00063   bool        terminating_bit           ();
00064   void        remaining_bytes           ( bool                          noTrailingBytesExpected );
00065 
00066   // coding tree unit (clause 7.3.8.2)
00067   void        coding_tree_unit          ( CodingStructure&              cs,     const UnitArea& area,     int (&qps)[2],   unsigned  ctuRsAddr );
00068 
00069   // sao (clause 7.3.8.3)
00070   void        sao                       ( CodingStructure&              cs,     unsigned        ctuRsAddr );
00071 
00072   void        readAlfCtuFilterIndex(CodingStructure&              cs, unsigned        ctuRsAddr);
00073 
00074   void ccAlfFilterControlIdc(CodingStructure &cs, const ComponentID compID, const int curIdx, uint8_t *filterControlIdc,
00075                              Position lumaPos, int filterCount);
00076 
00077   // coding (quad)tree (clause 7.3.8.4)
00078   void        coding_tree               ( CodingStructure&              cs,     Partitioner&    pm,       CUCtx& cuCtx, Partitioner* pPartitionerChroma = nullptr, CUCtx* pCuCtxChroma = nullptr);
00079   PartSplit   split_cu_mode             ( CodingStructure&              cs,     Partitioner&    pm );
00080   ModeType    mode_constraint           ( CodingStructure&              cs,     Partitioner&    pm,       const PartSplit splitMode );
00081 
00082   // coding unit (clause 7.3.8.5)
00083   void        coding_unit               ( CodingUnit&                   cu,     Partitioner&    pm,       CUCtx& cuCtx );
00084   void        cu_skip_flag              ( CodingUnit&                   cu );
00085   void        pred_mode                 ( CodingUnit&                   cu );
00086   void        bdpcm_mode                ( CodingUnit&                   cu,     const ComponentID compID );
00087   void        cu_pred_data              ( CodingUnit&                   cu );
00088   void        cu_bcw_flag               ( CodingUnit&                   cu );
00089   void        extend_ref_line           (CodingUnit&                     cu);
00090   void        intra_luma_pred_modes     ( CodingUnit&                   cu );
