00092   bool        intra_chroma_lmc_mode     ( PredictionUnit&               pu );
00093   void        intra_chroma_pred_mode    ( PredictionUnit&               pu );
00094   void        cu_residual               ( CodingUnit&                   cu,     Partitioner&    pm,       CUCtx& cuCtx );
00095   void        rqt_root_cbf              ( CodingUnit&                   cu );
00096   void        adaptive_color_transform(CodingUnit&             cu);
00097   void        sbt_mode                  ( CodingUnit&                   cu );
00098   void        end_of_ctu                ( CodingUnit&                   cu,     CUCtx&          cuCtx );
00099   void        mip_flag                  ( CodingUnit&                   cu );
00100   void        mip_pred_modes            ( CodingUnit&                   cu );
00101   void        mip_pred_mode             ( PredictionUnit&               pu );
00102   void        cu_palette_info           ( CodingUnit&                   cu,     ComponentID     compBegin, uint32_t numComp, CUCtx& cuCtx );
00103   void        cuPaletteSubblockInfo     ( CodingUnit&                   cu,     ComponentID     compBegin, uint32_t numComp, int subSetId, uint32_t& prevRunPos, unsigned& prevRunType );
00104   // prediction unit (clause 7.3.8.6)
00105   void        prediction_unit           ( PredictionUnit&               pu,     MergeCtx&       mrgCtx );
00106   void        merge_flag                ( PredictionUnit&               pu );
00107   void        merge_data                ( PredictionUnit&               pu );
00108   void        affine_flag               ( CodingUnit&                   cu );
00109   void        subblock_merge_flag       ( CodingUnit&                   cu );
00110   void        merge_idx                 ( PredictionUnit&               pu );
00111   void        mmvd_merge_idx(PredictionUnit&               pu);
00112   void        imv_mode                  ( CodingUnit&                   cu,     MergeCtx&       mrgCtx );
00113   void        affine_amvr_mode          ( CodingUnit&                   cu,     MergeCtx&       mrgCtx );
00114   void        inter_pred_idc            ( PredictionUnit&               pu );
00115   void        ref_idx                   ( PredictionUnit&               pu,     RefPicList      eRefList );
00116   void        mvp_flag                  ( PredictionUnit&               pu,     RefPicList      eRefList );
00117   void        Ciip_flag              ( PredictionUnit&               pu );
00118   void        smvd_mode              ( PredictionUnit&               pu );
00119 
00120 
00121   // transform tree (clause 7.3.8.8)
00122   void        transform_tree            ( CodingStructure&              cs, Partitioner&    pm, CUCtx& cuCtx, const PartSplit ispType = TU_NO_ISP, const int subTuIdx = -1 );
00123   bool        cbf_comp                  ( CodingStructure&              cs,     const CompArea& area,     unsigned depth, const bool prevCbf = false, const bool useISP = false );
00124 
00125   // mvd coding (clause 7.3.8.9)
00126   void        mvd_coding                ( Mv &rMvd );
00127 
00128   // transform unit (clause 7.3.8.10)
00129   void        transform_unit            ( TransformUnit&                tu,     CUCtx&          cuCtx, Partitioner& pm,        const int subTuCounter = -1 );
00130   void        cu_qp_delta               ( CodingUnit&                   cu,     int             predQP, int8_t& qp );
00131   void        cu_chroma_qp_offset       ( CodingUnit&                   cu );
00132 
00133   // residual coding (clause 7.3.8.11)
00134   void        residual_coding           ( TransformUnit&                tu,     ComponentID     compID, CUCtx& cuCtx );
00135   void        ts_flag                   ( TransformUnit&                tu,     ComponentID     compID );
00136   void        mts_idx                   ( CodingUnit&                   cu,     CUCtx&          cuCtx  );
00137   void        residual_lfnst_mode       ( CodingUnit&                   cu,     CUCtx&          cuCtx  );
00138   void        isp_mode                  ( CodingUnit&                   cu );
00139   int         last_sig_coeff            ( CoeffCodingContext&           cctx,   TransformUnit& tu, ComponentID   compID );
00140   void        residual_coding_subblock  ( CoeffCodingContext&           cctx,   TCoeff*         coeff, const int stateTransTable, int& state );
00141   void        residual_codingTS         ( TransformUnit&                tu,     ComponentID     compID );
00142   void        residual_coding_subblockTS( CoeffCodingContext&           cctx,   TCoeff*         coeff  );
00143   void        joint_cb_cr               ( TransformUnit&                tu,     const int cbfMask );
00144 
00145 
00146 private:
00147   unsigned    unary_max_symbol          ( unsigned ctxId0, unsigned ctxIdN, unsigned maxSymbol );
00148   unsigned    unary_max_eqprob          (                                   unsigned maxSymbol );
00149   unsigned    exp_golomb_eqprob         ( unsigned count );
00150   unsigned    get_num_bits_read         () { return m_BinDecoder.getNumBitsRead(); }
00151   unsigned    code_unary_fixed          ( unsigned ctxId, unsigned unary_max, unsigned fixed );
00152 
00153   void        xReadTruncBinCode(uint32_t& symbol, uint32_t maxSymbol);
00154   void        parseScanRotationModeFlag ( CodingUnit& cu,           ComponentID compBegin );
00155   void        xDecodePLTPredIndicator   ( CodingUnit& cu,           uint32_t maxPLTSize,   ComponentID compBegin );
00156   void        xAdjustPLTIndex           ( CodingUnit& cu,           Pel curLevel,          uint32_t idx, PelBuf& paletteIdx, PLTtypeBuf& paletteRunType, int maxSymbol, ComponentID compBegin );
00157 public:
00158 private:
00159   BinDecoderBase& m_BinDecoder;
00160   InputBitstream* m_Bitstream;
00161   ScanElement*    m_scanOrder;
00162 };
00163 
00164 
00165 class CABACDecoder
00166 {
00167 public:
00168   CABACDecoder()
00169     : m_CABACReaderStd  ( m_BinDecoderStd )
00170     , m_CABACReader     { &m_CABACReaderStd }
00171   {}
00172 
00173   CABACReader*                getCABACReader    ( int           id    )       { return m_CABACReader[id]; }
00174 
00175 private:
00176   BinDecoder_Std          m_BinDecoderStd;
00177   CABACReader             m_CABACReaderStd;
00178   CABACReader*            m_CABACReader[BPM_NUM-1];
00179 };
